"'$sourceHashes = [ordered]@{}
Get-ChildItem -Recurse -File | Where-Object { $_.FullName -notlike '"'*\\audit\\*' } | Sort-Object FullName | ForEach-Object {
    "'$relative = [IO.Path]::GetRelativePath((Get-Location).Path, $_.FullName).Replace('"'\\', '/')
