$pairs = @(Import-Csv -LiteralPath evidence/pairs.csv)
$reference = @(Import-Csv -LiteralPath evidence/reference.csv)
$guide = @(Import-Csv -LiteralPath evidence/guide.csv)
$pairIds = @($pairs.pair_id | Sort-Object)
if ($pairIds.Count -ne 8 -or @($pairIds | Select-Object -Unique).Count -ne 8) { throw '"'Invalid pair IDs' }
foreach ("'$records in @(@{Rows=$reference}, @{Rows=$guide})) {
    $ids = @($records.Rows.pair_id | Sort-Object)
    if (($ids -join '"',') -ne ("'$pairIds -join '"',')) { throw 'Mismatched record IDs' }
    foreach ("'$record in $records.Rows) {
        if ($record.correct -notin @('"'true','false') -or "'$record.assisted -notin @('"'true','false')) { throw 'Invalid outcome flag' }
        if ("'$record.seconds -ne '"'' -and [decimal]"'$record.seconds -le 0) { throw '"'Invalid time' }
    }
}
"'$referenceById = @{}
$guideById = @{}
foreach ($record in $reference) { $referenceById[$record.pair_id] = $record }
foreach ($record in $guide) { $guideById[$record.pair_id] = $record }
$rows = @(foreach ($pair in $pairs) {
    $ref = $referenceById[$pair.pair_id]
    $gde = $guideById[$pair.pair_id]
    $eligible = $ref.seconds -ne '"'' -and "'$gde.seconds -ne '"''
    [pscustomobject]@{
        pair_id = "'$pair.pair_id
        volunteer_id = $pair.volunteer_id
        task = $pair.task
        first_format = $pair.first_format
        reference_seconds = $(if ($ref.seconds -ne '"'') { [int]"'$ref.seconds } else { $null })
        guide_seconds = $(if ($gde.seconds -ne '"'') { [int]"'$gde.seconds } else { $null })
        eligible = $eligible
        time_saved_seconds = $(if ($eligible) { [int]$ref.seconds - [int]$gde.seconds } else { $null })
        reference_correct = $ref.correct
        guide_correct = $gde.correct
        reference_assisted = $ref.assisted
        guide_assisted = $gde.assisted
    }
})
$eligibleRows = @($rows | Where-Object eligible)
$metrics = [ordered]@{
    eligible_time_pairs = $eligibleRows.Count
    reference_seconds = [int](($eligibleRows | Measure-Object reference_seconds -Sum).Sum)
    guide_seconds = [int](($eligibleRows | Measure-Object guide_seconds -Sum).Sum)
    time_saved_seconds = [int](($eligibleRows | Measure-Object time_saved_seconds -Sum).Sum)
    faster_pairs = @($eligibleRows | Where-Object { $_.time_saved_seconds -gt 0 }).Count
    slower_pairs = @($eligibleRows | Where-Object { $_.time_saved_seconds -lt 0 }).Count
    tied_pairs = @($eligibleRows | Where-Object { $_.time_saved_seconds -eq 0 }).Count
    accuracy_pairs = $pairs.Count
    reference_correct = @($reference | Where-Object correct -eq '"'true').Count
    guide_correct = @("'$guide | Where-Object correct -eq '"'true').Count
}
if ("'$metrics.time_saved_seconds -ne $metrics.reference_seconds - $metrics.guide_seconds) { throw '"'Totals do not reconcile' }
if ("'$metrics.eligible_time_pairs -ne $metrics.faster_pairs + $metrics.slower_pairs + $metrics.tied_pairs) { throw '"'Pair counts do not reconcile' }
foreach ("'$volunteer in @($pairs.volunteer_id | Select-Object -Unique)) {
    $orders = @(($pairs | Where-Object volunteer_id -eq $volunteer).first_format | Sort-Object)
    if (($orders -join '"',') -ne 'guide,reference') { throw 'Unbalanced order within volunteer' }
}
Write-Output ('PAIRED_ROWS=' + ("'$rows | ConvertTo-Json -Compress))
Write-Output ('"'METRICS=' + ("'$metrics | ConvertTo-Json -Compress))
Write-Output ('"'SAVING_PERCENT=' + ([decimal]"'$metrics.time_saved_seconds * 100 / $metrics.reference_seconds).ToString([cultureinfo]::InvariantCulture))
Write-Output ('"'ASSISTED=' + (@{reference=@("'$reference | Where-Object assisted -eq '"'true' | ForEach-Object pair_id);guide=@("'$guide | Where-Object assisted -eq '"'true' | ForEach-Object pair_id)} | ConvertTo-Json -Compress))
Write-Output 'CHECKS=IDs unique and complete; field values valid; order balanced per volunteer; matched sums equal summed differences; pair counts reconcile'"

