'use strict';
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const root = process.cwd();
const baseline = {\"draft-summary.md\":\"4a7277ebee0f9597a1e066107380540c66590c6b81304218c91dc46cfd2135d4\",\"evidence/capture-notes.md\":\"e3a2c31c98402958d8c53a8a46279d64925299670c8ec39fac793fa487c43448\",\"evidence/guide.csv\":\"bfbb16f5ea6ab33ef26d7cf47125b375d0459e64cc83e628172d95aade87107a\",\"evidence/pairs.csv\":\"6c0bf3fa53e2fb5e1f8509ad21733b01fbda7a39511f7e55343a269bea5dce74\",\"evidence/reference.csv\":\"91109c551fa1fd29a6e5e59b8085a09b6581b2760f5adbca670f799d99818670\",\"guides/reference-card.txt\":\"236e2c9c478661eea6c9c5466c1ed7160ae1c283598e3468cd83e8a1decb5492\",\"guides/reorganized-guide.txt\":\"94acd3cebd66adbe2aeb94e53163fbde33656d8d7abb28b82c270f2219077fe5\",\"README.md\":\"8a4e73f42045a1670b8d856777664315f7acbc3c4c31739958377e0273fdf732\",\"study/protocol.md\":\"88e3dcebfadee2fcad57fe4777271851501b59587c97c66263ce6be7723a3a3e\",\"tools/check-evidence.cjs\":\"e149be4444c995be3d61b54fea91913d89025aaeaff962ffea5177ba8ac83e5f\"};
function readCsv(relative, header) {
  const lines = fs.readFileSync(path.join(root,relative),'utf8').trimEnd().split(/\\r?\\n/);
  assert.equal(lines.shift(),header.join(','));
  return lines.map(line => {
    const cells = line.split(',');
    assert.equal(cells.length,header.length);
    return Object.fromEntries(header.map((key,i)=>[key,cells[i]]));
  });
}
const pairs = readCsv('evidence/pairs.csv',['pair_id','volunteer_id','task','first_format']);
const reference = readCsv('evidence/reference.csv',['pair_id','seconds','correct','assisted']);
const guide = readCsv('evidence/guide.csv',['pair_id','seconds','correct','assisted']);
const expectedIds = pairs.map(row=>row.pair_id).sort();
assert.equal(new Set(expectedIds).size,8);
assert.equal(new Set(pairs.map(row=>row.volunteer_id)).size,4);
function index(rows) {
  assert.equal(rows.length,new Set(rows.map(row=>row.pair_id)).size);
  assert.deepEqual(rows.map(row=>row.pair_id).sort(),expectedIds);
  for (const row of rows) {
    assert.ok(['true','false'].includes(row.correct));
    assert.ok(['true','false'].includes(row.assisted));
    assert.ok(row.seconds==='' || (Number.isFinite(Number(row.seconds)) && Number(row.seconds)>0));
  }
  return new Map(rows.map(row=>[row.pair_id,row]));
}
const ref = index(reference);
const gde = index(guide);
function compute(referenceRows, guideRows) {
  const r = index(referenceRows);
  const g = index(guideRows);
  const totals = {eligible_time_pairs:0,reference_seconds:0,guide_seconds:0,time_saved_seconds:0,faster_pairs:0,slower_pairs:0,tied_pairs:0,accuracy_pairs:0,reference_correct:0,guide_correct:0};
  for (const pair of pairs) {
    const left = r.get(pair.pair_id);
    const right = g.get(pair.pair_id);
    totals.accuracy_pairs++;
    totals.reference_correct += Number(left.correct==='true');
    totals.guide_correct += Number(right.correct==='true');
    if (left.seconds==='' || right.seconds==='') continue;
    const referenceSeconds = Number(left.seconds);
    const guideSeconds = Number(right.seconds);
    totals.eligible_time_pairs++;
    totals.reference_seconds += referenceSeconds;
    totals.guide_seconds += guideSeconds;
    const difference = referenceSeconds-guideSeconds;
    totals.time_saved_seconds += difference;
    if (difference>0) totals.faster_pairs++;
    else if (difference<0) totals.slower_pairs++;
    else totals.tied_pairs++;
  }
  return totals;
}
const computed = compute(reference,guide);
