}
const eligibleIds = pairs.filter(row=>ref.get(row.pair_id).seconds"'!=='"'' && gde.get(row.pair_id).seconds"'!=='"'').map(row=>row.pair_id);
assert.deepEqual(eligibleIds,['P1','P2','P3','P4','P5','P6','P8']);
const pairedAccuracy = {bothCorrect:0,guideOnlyCorrect:0,referenceOnlyCorrect:0,bothIncorrect:0};
for(const pair of pairs) {
  const r=ref.get(pair.pair_id).correct==='true';
  const g=gde.get(pair.pair_id).correct==='true';
  pairedAccuracy[r?(g?'bothCorrect':'referenceOnlyCorrect'):(g?'guideOnlyCorrect':'bothIncorrect')]++;
}
assert.deepEqual(pairedAccuracy,{bothCorrect:6,guideOnlyCorrect:1,referenceOnlyCorrect:1,bothIncorrect:0});
for(const [relative,expectedHash] of Object.entries(baseline)) {
  const observedHash=crypto.createHash('sha256').update(fs.readFileSync(path.join(root,relative))).digest('hex');
